const $=s=>document.querySelector(s),base='downloads/model-documents/';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=async p=>{const r=await fetch(p);if(!r.ok)throw Error('无法读取资料（'+r.status+'）');return r.json()};
let manifest,selected,data,audit,page=0;
const link=(id,suffix,label)=>`<a download href="${base+encodeURIComponent(id)+suffix}">${label}</a>`;
function list(){const q=$('#search').value.toLowerCase(),f=$('#family').value,c=$('#coverage').value;const ms=manifest.models.filter(m=>(!q||m.name.toLowerCase().includes(q))&&(!f||m.family===f)&&(!c||(c==='layers'?m.layers>0:m.layers===0)));$('#count').textContent=`显示 ${ms.length} / ${manifest.models.length} 个独立条目；${manifest.models.filter(m=>m.layers>0).length} 个有逐层展开，${manifest.models.filter(m=>!m.layers).length} 个资料缺口。独立审查进行中。`;$('#models').innerHTML=ms.map(m=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${esc(m.family)}</td><td>${esc(m.status)}${m.gap?`<small>${esc(m.gap)}</small>`:''}</td><td>${m.layers} / ${m.rows}</td><td>${link(m.id,'.xlsx','XLSX')}${link(m.id,'.csv','算子 CSV')}${link(m.id,'-parameters.csv','参数 CSV')}<a href="?model=${encodeURIComponent(m.id)}">在线预览</a></td></tr>`).join('')}
async function preview(){const view=$('#view').value;$('#audit-filter-label').hidden=view!=='audit';let headers,rows;
 if(view==='audit'){
  if(selected.name!=='Kimi-K3'){$('#row-count').textContent='模板仅用于K3直接比对；此模型没有K3原值可逐项比较。';$('#preview-table').innerHTML='';return}
  audit??=await get(base+'K3-template-cell-audit.json');headers=['原sheet','原单元格','模块','算子','字段','模板原值','独立分析值 / 公式','比对状态','差异类别','原因','固定版本来源','新文档定位'];rows=audit.filter(r=>!$('#audit-filter').value||r.comparison_status===$('#audit-filter').value).map(r=>[r.sheet,r.cell,r.module,r.operator,r.field,r.original,r.verified_or_formula,r.comparison_status,r.classification,r.reason,r.fixed_sources,r.analysis_location]);
 }else if(view==='parameters'){headers=['符号 / 字段','定义 / 配置值'];rows=[...manifest.template.symbols,['B范围','1..16，默认1'],['S范围',data.isEncoder?'本编码器不适用verify长度；使用L_text，tokens=B*L_text':'verify长度1..8，默认1'],['TP / EP','默认1，须为正整数；运行场景假设'],['L_KV',data.isEncoder?'无解码历史KV缓存；Q/K/V同输入长度L_text':'独立未知，不是S'],...Object.entries(data.params),...data.config.map(([k,v])=>[k,typeof v==='object'?JSON.stringify(v):v])];}
 else{headers=data.headers;rows=data.rows}
 const q=$('#row-search').value.toLowerCase();rows=rows.filter(r=>!q||r.some(x=>String(x??'').toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(rows.length/40));page=Math.min(page,pages-1);$('#row-count').textContent=`${rows.length} 条；第 ${page+1} / ${pages} 页，每页40条。完整内容请下载独立文件。`;$('#previous').disabled=page===0;$('#next').disabled=page>=pages-1;$('#preview-table').innerHTML='<thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(page*40,(page+1)*40).map(r=>`<tr class="${view==='audit'?({'差异':'state-diff','新增':'state-new','待核验':'state-pending'}[r[7]]||''):''}">`+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody>';
}
try{manifest=await get(base+'manifest.json');const params=new URLSearchParams(location.search);$('#family').value=params.get('family')||'';list();for(const id of ['search','family','coverage'])$('#'+id).addEventListener('input',list);selected=manifest.models.find(m=>m.id===params.get('model'));if(selected){$('#catalog').hidden=true;$('#preview').hidden=false;$('#model-title').textContent=selected.name;$('#model-status').textContent=selected.status+'；'+selected.layers+'个配置层 / '+selected.rows+'行。'+(selected.gap||'');$('#model-downloads').innerHTML=link(selected.id,'.xlsx','下载本模型 XLSX')+link(selected.id,'.csv','下载算子 CSV')+link(selected.id,'-parameters.csv','下载参数 CSV');data=await get(base+encodeURIComponent(selected.id)+'.json');$('#view').value=params.get('view')||'operators';for(const id of ['view','row-search','audit-filter'])$('#'+id).addEventListener('input',()=>{page=0;preview()});$('#previous').onclick=()=>{page--;preview()};$('#next').onclick=()=>{page++;preview()};await preview();}}catch(e){$('#count').textContent=e.message;$('#row-count').textContent=e.message}
